INSERT INTO task_type_template (type_id, locale, render_target, template_text, spec_version)
VALUES
    ('G9-ALG-001', 'ru-KZ', 'plaintext', 'Найдите коэффициент при x^{{x_power}}y^{{y_power}} в разложении (x + y)^{{n}}.', '1.0.0-draft'),
    ('G9-DIS-001', 'ru-KZ', 'plaintext', 'Вычислите {{operation}}({{n}}, {{k}}). Здесь P(n, k) — число размещений, C(n, k) — число сочетаний.', '1.0.0-draft'),
    ('G9-FUN-001', 'ru-KZ', 'plaintext', 'Арифметическая прогрессия задана первым членом a₁ = {{a1}} и разностью d = {{d}}. Найдите {{target}}.', '1.0.0-draft'),
    ('G9-FUN-002', 'ru-KZ', 'plaintext', 'Геометрическая прогрессия задана первым членом a₁ = {{a1}} и знаменателем r = {{r}}. Найдите {{target}}.', '1.0.0-draft'),
    ('G9-FUN-003', 'ru-KZ', 'plaintext', 'При преобразовании графика y = f(x) в y = f(x) {{operator}} {{amount}} сдвигается ли график вверх? Ответьте true или false.', '1.0.0-draft'),
    ('G9-FUN-004', 'ru-KZ', 'plaintext', 'Арифметическая прогрессия задана первым членом a₁ = {{a1}} и разностью d = {{d}}. Найдите сумму её первых {{n}} членов.', '1.0.0-draft'),
    ('G9-FUN-005', 'ru-KZ', 'plaintext', 'Геометрическая прогрессия задана первым членом a₁ = {{a1}} и знаменателем r = {{r}}. Найдите сумму её первых {{n}} членов.', '1.0.0-draft'),
    ('G9-GEO-001', 'ru-KZ', 'plaintext', 'В треугольнике сторона a = {{a}} лежит напротив угла A = {{A}}°. Угол B равен {{B}}°. По теореме синусов найдите сторону b, лежащую напротив угла B.', '1.0.0-draft'),
    ('G9-GEO-002', 'ru-KZ', 'plaintext', 'В подобных треугольниках соответствующая сторона первого треугольника равна {{a}}, коэффициент подобия равен {{scale}}. Найдите соответствующую сторону второго треугольника.', '1.0.0-draft'),
    ('G9-GEO-003', 'ru-KZ', 'plaintext', 'По теореме синусов a/sin(A) = b/sin(B). Если a = {{a}}, A = {{A}}° и B = {{B}}°, найдите b.', '1.0.0-draft')
